baseCss:
.aha-features{
  container:aha-features / inline-size;
  position:relative;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
  overflow:hidden;
}
.aha-features *{box-sizing:border-box}
:where(.aha-features) :is(h2,h3,p,ul,ol,figure){margin:0;padding:0}
:where(.aha-features) :is(ul,ol){list-style:none}
.aha-features__inner{max-width:80rem;margin:0 auto;padding:var(--aha-space-96) var(--aha-space-32)}
.aha-features__header{max-width:48rem;margin:0 0 var(--aha-space-64)}
.aha-features__header--center{margin-inline:auto;text-align:center}
.aha-features__eyebrow{
  margin:0 0 var(--aha-space-12);
  font-size:var(--aha-size-sm);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);
  text-transform:uppercase;
  color:var(--aha-color-primary);
}
.aha-features__title{
  font-family:var(--aha-font-display);
  font-size:var(--aha-size-h2);
  line-height:var(--aha-line-height-tight);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-features__lead{
  margin-top:var(--aha-space-20);
  font-size:var(--aha-size-xl);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features__icon{
  display:inline-flex;flex:none;align-items:center;justify-content:center;
  width:var(--aha-space-48);height:var(--aha-space-48);
  border:1px solid var(--aha-border-default);
  border-radius:var(--aha-radius-lg);
  background:var(--aha-white);
  color:var(--aha-icon-strong);
  box-shadow:0 var(--aha-space-2) var(--aha-space-4) var(--aha-ink-a10);
}
.aha-features__icon--accent{border-color:transparent;border-radius:var(--aha-radius-pill);background:var(--aha-bg-accent);color:var(--aha-color-primary);box-shadow:none}
.aha-features__icon--solid{border-color:transparent;background:var(--aha-color-primary);color:var(--aha-icon-inverse);box-shadow:none}
.aha-features__item-title{font-size:var(--aha-size-h6);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-features__item-text{margin-top:var(--aha-space-8);font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-features__list{display:flex;flex-direction:column;gap:var(--aha-space-40)}
.aha-features__list-item{display:flex;align-items:flex-start;gap:var(--aha-space-16)}
.aha-features__list-item .aha-features__item-title{margin-top:var(--aha-space-12)}
.aha-features__link{
  display:inline-flex;align-items:center;gap:var(--aha-space-6);
  margin-top:var(--aha-space-16);
  border-radius:var(--aha-radius-xs);
  font-size:var(--aha-size-l);
  font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-link);
  text-decoration:none;
  transition:color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-features__link:hover{color:var(--aha-text-link-hover)}
.aha-features__link:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-features__actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);margin-top:var(--aha-space-32)}
.aha-features__button{
  display:inline-flex;align-items:center;justify-content:center;
  min-height:var(--aha-control-height-button-lg);
  padding:0 var(--aha-space-20);
  border:1px solid transparent;
  border-radius:var(--aha-radius-pill);
  font-family:inherit;
  font-size:var(--aha-size-l);
  font-weight:var(--aha-weight-semibold);
  text-decoration:none;
  cursor:pointer;
  background:var(--aha-button-primary-bg);
  color:var(--aha-button-primary-text);
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out),transform var(--aha-motion-fast) var(--aha-ease-out);
}
.aha-features__button:hover{background:var(--aha-button-primary-bg-hover)}
.aha-features__button:active{background:var(--aha-button-primary-bg-press);transform:translateY(1px)}
.aha-features__button:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-features__button--secondary{background:var(--aha-button-default-bg);color:var(--aha-button-default-text);border-color:var(--aha-button-default-border)}
.aha-features__button--secondary:hover{background:var(--aha-button-default-bg-hover);border-color:var(--aha-button-default-border-hover)}
.aha-features__button--secondary:active{background:var(--aha-button-default-bg-hover);border-color:var(--aha-button-default-border-press)}
.aha-features__mock{
  display:flex;flex-direction:column;
  width:100%;
  background:var(--aha-bg-container);
  border:1px solid var(--aha-border-default);
  border-radius:var(--aha-radius-lg);
  box-shadow:0 var(--aha-space-12) var(--aha-space-40) var(--aha-ink-a10);
  overflow:hidden;
  text-align:left;
}
.aha-features__mock-body{display:grid;grid-template-columns:auto minmax(0,1fr);flex:1}
.aha-features__mock-side{display:flex;flex-direction:column;gap:var(--aha-space-8);padding:var(--aha-space-12);border-right:1px solid var(--aha-split);background:var(--aha-bg-container-secondary)}
.aha-features__mock-side span{display:block;width:var(--aha-space-48);aspect-ratio:16 / 9;border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-xs);background:var(--aha-white)}
.aha-features__mock-side .is-active{border-color:var(--aha-color-primary);background:var(--aha-bg-accent)}
.aha-features__mock-main{display:flex;flex-direction:column;justify-content:center;gap:var(--aha-space-16);padding:var(--aha-space-24)}
.aha-features__mock-q{font-size:var(--aha-size-h6);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-features__bar-top{display:flex;justify-content:space-between;gap:var(--aha-space-12);margin:0 0 var(--aha-space-6);font-size:var(--aha-size-default);color:var(--aha-text-secondary)}
.aha-features__bar-top b{color:var(--aha-text-default);font-weight:var(--aha-weight-semibold)}
.aha-features__track{height:var(--aha-space-12);border-radius:var(--aha-radius-pill);background:var(--aha-bg-accent);overflow:hidden}
.aha-features__fill{height:100%;border-radius:var(--aha-radius-pill);background:var(--aha-color-primary)}
.aha-features__fill--soft{background:var(--aha-vivid-pink-30)}
.aha-features__cloud{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:var(--aha-space-4) var(--aha-space-16)}
.aha-features__word{font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-tight);color:var(--aha-text-secondary)}
.aha-features__word--xl{font-size:var(--aha-size-h3);color:var(--aha-color-primary)}
.aha-features__word--l{font-size:var(--aha-size-h4);color:var(--aha-text-default)}
.aha-features__word--m{font-size:var(--aha-size-xl)}
.aha-features__word--s{font-size:var(--aha-size-default);color:var(--aha-text-tertiary)}
.aha-features__board{display:flex;flex-direction:column;gap:var(--aha-space-8)}
.aha-features__board li{display:flex;align-items:center;gap:var(--aha-space-12);padding:var(--aha-space-8) var(--aha-space-12);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-default);font-size:var(--aha-size-default);color:var(--aha-text-default)}
.aha-features__board li:first-child{border-color:var(--aha-color-primary);background:var(--aha-bg-accent)}
.aha-features__rank{display:inline-flex;align-items:center;justify-content:center;width:var(--aha-space-24);height:var(--aha-space-24);border-radius:var(--aha-radius-pill);background:var(--aha-bg-container-secondary);font-weight:var(--aha-weight-semibold)}
.aha-features__who{flex:1}
.aha-features__photo{
  display:flex;align-items:center;justify-content:center;
  width:100%;height:100%;min-height:inherit;
  background:var(--aha-bg-container-secondary);
  border-radius:var(--aha-radius-marketing);
  color:var(--aha-icon-muted);
  overflow:hidden;
}
.aha-features__photo img{display:block;width:100%;height:100%;object-fit:cover}
.aha-features__checks{display:flex;flex-direction:column;gap:var(--aha-space-16);margin-top:var(--aha-space-32)}
.aha-features__checks li{display:flex;align-items:flex-start;gap:var(--aha-space-12);font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-features__check{display:inline-flex;flex:none;align-items:center;justify-content:center;width:var(--aha-space-28);height:var(--aha-space-28);border-radius:var(--aha-radius-pill);background:var(--aha-bg-accent);color:var(--aha-color-primary)}
.aha-features__phone{
  width:min(100%,19rem);aspect-ratio:9 / 16.5;margin-inline:auto;
  border:var(--aha-space-8) solid var(--aha-gray-100);
  border-radius:calc(var(--aha-radius-marketing) * 2);
  background:var(--aha-white);
  box-shadow:0 var(--aha-space-12) var(--aha-space-40) var(--aha-ink-a10);
  overflow:hidden;
}
.aha-features__phone-screen{display:flex;flex-direction:column;gap:var(--aha-space-12);height:100%;padding:var(--aha-space-40) var(--aha-space-16) var(--aha-space-24);text-align:left}
.aha-features__phone-code{font-size:var(--aha-size-sm);color:var(--aha-text-tertiary);text-align:center}
.aha-features__phone-q{margin:var(--aha-space-12) 0;font-size:var(--aha-size-h6);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading)}
.aha-features__phone-option{display:flex;align-items:center;min-height:var(--aha-control-height-lg);padding:0 var(--aha-space-16);border:1px solid var(--aha-border-strong);border-radius:var(--aha-radius-default);font-size:var(--aha-size-default);color:var(--aha-text-default)}
.aha-features__phone-option.is-picked{border-color:var(--aha-color-primary);background:var(--aha-bg-accent);font-weight:var(--aha-weight-semibold)}
.aha-features__phone-submit{display:flex;align-items:center;justify-content:center;min-height:var(--aha-control-height-lg);margin-top:auto;border-radius:var(--aha-radius-pill);background:var(--aha-color-primary);font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);color:var(--aha-text-inverse)}
.aha-features__chart{position:relative;width:100%;padding-bottom:var(--aha-space-40)}
.aha-features__chart-card{padding:var(--aha-space-24);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-lg);background:var(--aha-bg-container);box-shadow:0 var(--aha-space-12) var(--aha-space-40) var(--aha-ink-a10)}
.aha-features__chart-title{padding-bottom:var(--aha-space-16);border-bottom:1px solid var(--aha-split);font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold)}
.aha-features__cols{display:flex;align-items:flex-end;gap:var(--aha-space-8);height:var(--aha-space-100);margin-top:var(--aha-space-24)}
.aha-features__col{flex:1;border-radius:var(--aha-radius-xs) var(--aha-radius-xs) 0 0;background:var(--aha-vivid-pink-30)}
.aha-features__col:nth-last-child(-n+3){background:var(--aha-color-primary)}
.aha-features__months{display:flex;justify-content:space-between;margin-top:var(--aha-space-8);font-size:var(--aha-size-sm);color:var(--aha-text-tertiary)}
.aha-features__ring{
  position:absolute;right:calc(var(--aha-space-24) * -1);bottom:0;
  display:grid;place-items:center;
  width:var(--aha-space-100);aspect-ratio:1;
  border-radius:var(--aha-radius-pill);
  background:var(--aha-white);
  box-shadow:0 var(--aha-space-12) var(--aha-space-40) var(--aha-ink-a10);
}
.aha-features__ring::before{
  content:"";position:absolute;inset:var(--aha-space-8);
  border:var(--aha-space-8) solid var(--aha-vivid-pink-30);
  border-top-color:var(--aha-color-primary);border-right-color:var(--aha-color-primary);border-bottom-color:var(--aha-color-primary);
  border-radius:var(--aha-radius-pill);
  transform:rotate(45deg);
}
.aha-features__ring-text{position:relative;display:flex;flex-direction:column;align-items:center;font-size:var(--aha-size-sm);color:var(--aha-text-secondary);line-height:var(--aha-line-height-tight)}
.aha-features__ring-text b{font-size:var(--aha-size-xl);color:var(--aha-text-default)}
.aha-features__play{
  position:absolute;top:50%;left:50%;
  display:inline-flex;align-items:center;justify-content:center;
  width:var(--aha-space-80);height:var(--aha-space-80);
  padding:0;border:0;border-radius:var(--aha-radius-pill);
  background:var(--aha-white);color:var(--aha-color-primary);
  box-shadow:0 var(--aha-space-12) var(--aha-space-40) var(--aha-ink-a30);
  transform:translate(-50%,-50%);
  cursor:pointer;
  transition:transform var(--aha-motion-mid) var(--aha-ease-out);
}
.aha-features__play:hover{transform:translate(-50%,-50%) scale(1.06)}
.aha-features__play:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-4)}
@media (prefers-reduced-motion:reduce){
  .aha-features__play,.aha-features__button,.aha-features__link{transition:none}
  .aha-features__play:hover{transform:translate(-50%,-50%)}
  .aha-features__button:active{transform:none}
}

layouts.css:
.aha-features--alternating-photos .aha-features__rows{display:flex;flex-direction:column;gap:var(--aha-space-96)}
.aha-features--alternating-photos .aha-features__row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-96);align-items:center}
.aha-features--alternating-photos .aha-features__row-title{margin-top:var(--aha-space-20);font-family:var(--aha-font-display);font-size:var(--aha-size-h3);line-height:var(--aha-line-height-tight);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-features--alternating-photos .aha-features__row-text{margin-top:var(--aha-space-16);font-size:var(--aha-size-xl);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-features--alternating-photos .aha-features__inner{padding-bottom:0}
.aha-features--alternating-photos .aha-features__bleed{padding-bottom:var(--aha-space-96)}
.aha-features--alternating-photos .aha-features__row{gap:0}
.aha-features--alternating-photos .aha-features__copy{padding-left:max(var(--aha-space-32),calc((100cqw - 80rem) / 2 + var(--aha-space-32)));padding-right:var(--aha-space-96)}
.aha-features--alternating-photos .aha-features__row:nth-child(even) .aha-features__copy{order:2;padding-left:var(--aha-space-96);padding-right:max(var(--aha-space-32),calc((100cqw - 80rem) / 2 + var(--aha-space-32)))}
.aha-features--alternating-photos .aha-features__visual{align-self:stretch;min-height:35rem}
.aha-features--alternating-photos .aha-features__photo{border-radius:0}
.aha-features--alternating-photos .aha-features__checks{padding-left:var(--aha-space-8)}
@container aha-features (max-width:991px){
  .aha-features--alternating-photos .aha-features__row{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-40)}
  .aha-features--alternating-photos .aha-features__copy, .aha-features--alternating-photos .aha-features__row:nth-child(even) .aha-features__copy{order:0;padding:0 var(--aha-space-32)}
  .aha-features--alternating-photos .aha-features__visual{min-height:20rem}
}
@container aha-features (max-width:767px){
  .aha-features--alternating-photos .aha-features__inner{padding:var(--aha-space-64) var(--aha-space-24) 0}
  .aha-features--alternating-photos .aha-features__bleed{padding-bottom:var(--aha-space-64)}
  .aha-features--alternating-photos .aha-features__copy, .aha-features--alternating-photos .aha-features__row:nth-child(even) .aha-features__copy{padding:0 var(--aha-space-24)}
  .aha-features--alternating-photos .aha-features__visual{min-height:15rem}
  .aha-features--alternating-photos .aha-features__row-title{font-size:var(--aha-size-h4)}
  .aha-features--alternating-photos .aha-features__row-text{font-size:var(--aha-size-l)}
}

.aha-features--icon-list-video .aha-features__band{background:var(--aha-bg-container-secondary)}
.aha-features--icon-list-video .aha-features__band .aha-features__inner{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-96);padding-bottom:calc(var(--aha-space-100) + var(--aha-space-60));align-items:start}
.aha-features--icon-list-video .aha-features__band .aha-features__header{margin:0}
.aha-features--icon-list-video .aha-features__band .aha-features__list-item{max-width:35rem}
.aha-features--icon-list-video .aha-features__band .aha-features__list-item .aha-features__item-title{margin-top:var(--aha-space-8)}
.aha-features--icon-list-video .aha-features__overlap{max-width:80rem;margin:calc(var(--aha-space-96) * -1) auto 0;padding:0 var(--aha-space-32) var(--aha-space-96);position:relative}
.aha-features--icon-list-video .aha-features__video, .aha-features--icon-list-video .aha-features__wide{position:relative;margin-inline:auto;overflow:hidden;border-radius:var(--aha-radius-marketing)}
.aha-features--icon-list-video .aha-features__video{max-width:60rem;aspect-ratio:16 / 9;background:var(--aha-gray-30);box-shadow:0 var(--aha-space-24) var(--aha-space-64) var(--aha-ink-a30)}
.aha-features--icon-list-video .aha-features__video .aha-features__photo, .aha-features--icon-list-video .aha-features__wide .aha-features__photo{position:absolute;inset:0;border-radius:0;background:var(--aha-gray-30)}
.aha-features--icon-list-video .aha-features__wide{min-height:32rem;background:var(--aha-gray-30)}
.aha-features--icon-list-video .aha-features__wide .aha-features__photo{min-height:32rem}
@container aha-features (max-width:991px){
  .aha-features--icon-list-video .aha-features__band .aha-features__inner{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-48);padding-bottom:var(--aha-space-100)}
}
@container aha-features (max-width:767px){
  .aha-features--icon-list-video .aha-features__band .aha-features__inner{padding:var(--aha-space-64) var(--aha-space-24) var(--aha-space-80)}
  .aha-features--icon-list-video .aha-features__overlap{margin-top:calc(var(--aha-space-56) * -1);padding:0 var(--aha-space-24) var(--aha-space-64)}
  .aha-features--icon-list-video .aha-features__title{font-size:var(--aha-size-h3)}
  .aha-features--icon-list-video .aha-features__lead{font-size:var(--aha-size-l)}
  .aha-features--icon-list-video .aha-features__play{width:var(--aha-space-60);height:var(--aha-space-60)}
  .aha-features--icon-list-video .aha-features__wide, .aha-features--icon-list-video .aha-features__wide .aha-features__photo{min-height:16rem}
}

.aha-features--icon-list-wide-photo .aha-features__band{background:var(--aha-bg-container-secondary)}
.aha-features--icon-list-wide-photo .aha-features__band .aha-features__inner{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-96);padding-bottom:calc(var(--aha-space-100) + var(--aha-space-60));align-items:start}
.aha-features--icon-list-wide-photo .aha-features__band .aha-features__header{margin:0}
.aha-features--icon-list-wide-photo .aha-features__band .aha-features__list-item{max-width:35rem}
.aha-features--icon-list-wide-photo .aha-features__band .aha-features__list-item .aha-features__item-title{margin-top:var(--aha-space-8)}
.aha-features--icon-list-wide-photo .aha-features__overlap{max-width:80rem;margin:calc(var(--aha-space-96) * -1) auto 0;padding:0 var(--aha-space-32) var(--aha-space-96);position:relative}
.aha-features--icon-list-wide-photo .aha-features__video, .aha-features--icon-list-wide-photo .aha-features__wide{position:relative;margin-inline:auto;overflow:hidden;border-radius:var(--aha-radius-marketing)}
.aha-features--icon-list-wide-photo .aha-features__video{max-width:60rem;aspect-ratio:16 / 9;background:var(--aha-gray-30);box-shadow:0 var(--aha-space-24) var(--aha-space-64) var(--aha-ink-a30)}
.aha-features--icon-list-wide-photo .aha-features__video .aha-features__photo, .aha-features--icon-list-wide-photo .aha-features__wide .aha-features__photo{position:absolute;inset:0;border-radius:0;background:var(--aha-gray-30)}
.aha-features--icon-list-wide-photo .aha-features__wide{min-height:32rem;background:var(--aha-gray-30)}
.aha-features--icon-list-wide-photo .aha-features__wide .aha-features__photo{min-height:32rem}
@container aha-features (max-width:991px){
  .aha-features--icon-list-wide-photo .aha-features__band .aha-features__inner{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-48);padding-bottom:var(--aha-space-100)}
}
@container aha-features (max-width:767px){
  .aha-features--icon-list-wide-photo .aha-features__band .aha-features__inner{padding:var(--aha-space-64) var(--aha-space-24) var(--aha-space-80)}
  .aha-features--icon-list-wide-photo .aha-features__overlap{margin-top:calc(var(--aha-space-56) * -1);padding:0 var(--aha-space-24) var(--aha-space-64)}
  .aha-features--icon-list-wide-photo .aha-features__title{font-size:var(--aha-size-h3)}
  .aha-features--icon-list-wide-photo .aha-features__lead{font-size:var(--aha-size-l)}
  .aha-features--icon-list-wide-photo .aha-features__play{width:var(--aha-space-60);height:var(--aha-space-60)}
  .aha-features--icon-list-wide-photo .aha-features__wide, .aha-features--icon-list-wide-photo .aha-features__wide .aha-features__photo{min-height:16rem}
}

.aha-features--icons-chart-mockup .aha-features__trio{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr) minmax(0,1fr);gap:var(--aha-space-32);align-items:start}
